const source = $('Load Active Sources').item.json;
const title = String($json.title ?? '').trim();
const rawUrl = String($json.link ?? '').trim();
const rawDate = $json.isoDate ?? $json.pubDate ?? $json.published ?? $json.date;

const reject = (reason, hostname = '') => ({
  json: {
    item_valid: false,
    source_id: Number(source.source_id),
    source_name: String(source.source_name),
    rejection_reason: reason,
    rejected_hostname: String(hostname).slice(0, 253),
    rejected_url: rawUrl.slice(0, 4000),
  },
});

if (!title || title.length > 500) {
  return reject('invalid_title');
}

const publishedAt = new Date(rawDate);
if (!rawDate || Number.isNaN(publishedAt.getTime())) {
  return reject('invalid_publication_date');
}

if (!rawUrl || rawUrl.length > 4000) {
  return reject('invalid_article_url');
}

const urlMatch = rawUrl.match(/^https:\/\/([^\/?#:@]+)(?::(\d+))?(?:[\/?#]|$)/i);
if (!urlMatch) {
  return reject('invalid_article_url');
}

const hostname = urlMatch[1].toLowerCase();
const port = urlMatch[2] ?? '';
const allowedHosts = Array.isArray(source.allowed_hosts)
  ? source.allowed_hosts.map((host) => String(host).toLowerCase())
  : [];

if ((port && port !== '443') || !allowedHosts.includes(hostname)) {
  return reject('article_host_not_allowed', hostname);
}

const withoutFragment = rawUrl.split('#', 1)[0];
const questionMarkIndex = withoutFragment.indexOf('?');
let canonicalUrl = withoutFragment;
if (questionMarkIndex >= 0) {
  const baseUrl = withoutFragment.slice(0, questionMarkIndex);
  const trackingKeys = new Set(['fbclid', 'gclid', 'dclid', 'mc_cid', 'mc_eid']);
  const retainedParameters = withoutFragment
    .slice(questionMarkIndex + 1)
    .split('&')
    .filter(Boolean)
    .filter((parameter) => {
      const key = parameter.split('=', 1)[0].toLowerCase();
      return !key.startsWith('utm_') && !trackingKeys.has(key);
    })
    .sort();
  canonicalUrl = retainedParameters.length > 0
    ? `${baseUrl}?${retainedParameters.join('&')}`
    : baseUrl;
}

const feedGuid = String($json.guid ?? $json.id ?? canonicalUrl).trim();
if (feedGuid.length > 1000) {
  return reject('feed_guid_too_long', hostname);
}

return {
  json: {
    item_valid: true,
    source_id: Number(source.source_id),
    source_name: String(source.source_name),
    original_url: canonicalUrl,
    title,
    feed_guid: feedGuid,
    published_at: publishedAt.toISOString(),
  },
};

const seen = new Set();
const sources = [];
for (const item of $input.all()) {
  const sourceId = Number(item.json.source_id);
  if (!Number.isSafeInteger(sourceId) || sourceId <= 0 || seen.has(sourceId)) {
    continue;
  }
  seen.add(sourceId);
  sources.push({ json: { source_id: sourceId } });
}
return sources;
